/**
 * Build src/data/berryFlavors.ts: each game's own berry flavours and smoothness,
 * for #19 (Pokéblocks and Poffins).
 *
 * WHY A GENERATED FILE: the Berry Blender and the Poffin pot read these exact
 * numbers, and the bundle's berries.json is PokéAPI's single modern table. So
 * the tool reads the games' tables, extracted from the pinned disassemblies
 * (scripts/trainers/sources.mjs), not hand-typed:
 *   Gen 3: pokeruby and pokeemerald src/berry.c gBerries (must agree);
 *   Gen 4: pokeplatinum res/items/data/<name>_berry.json berryData.
 * Gen 3 is in berry-number order (Cheri = 1 ... Enigma = 43); Gen 4 is keyed
 * by name, ordered by berries.json's id. Throws on anything missing.
 *
 * Usage: node scripts/build-berry-data.mjs
 */

import { existsSync, readFileSync, writeFileSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'
import { REPOS, ensureSources } from './trainers/sources.mjs'

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..')
const dirs = ensureSources(join(ROOT, '.cache/trainers'))
const FIELDS = ['spicy', 'dry', 'sweet', 'bitter', 'sour', 'smoothness']

function gen3(repo) {
  const text = readFileSync(join(dirs[repo], 'src/berry.c'), 'utf8')
  const start = text.indexOf('gBerries[]')
  if (start < 0) throw new Error(`${repo}: no gBerries`)
  const body = text.slice(start, text.indexOf('\n};', start))
  const out = []
  // Emerald writes .name = _("CHERI"); Ruby writes .name = NAME_CHERI_BERRY.
  for (const block of body.split(/\.name\s*=\s*/).slice(1)) {
    const m = /^(?:_\("(\w+)"\)|NAME_(\w+)_BERRY)/.exec(block)
    if (!m) throw new Error(`${repo}: unreadable berry name: ${block.slice(0, 30)}`)
    const name = (m[1] ?? m[2]).toLowerCase()
    const v = FIELDS.map((f) => {
      const m = new RegExp(`\\.${f}\\s*=\\s*(\\d+)`).exec(block)
      if (!m) throw new Error(`${repo}: ${name} has no .${f}`)
      return Number(m[1])
    })
    out.push([name, ...v])
  }
  return out
}

const ruby = gen3('pokeruby')
const emerald = gen3('pokeemerald')
if (emerald.length !== 43) throw new Error(`expected 43 Gen 3 berries, got ${emerald.length}`)
if (JSON.stringify(ruby) !== JSON.stringify(emerald))
  throw new Error('Ruby and Emerald berry tables differ -- the tool assumes one Gen 3 table')

const berries = Object.values(
  JSON.parse(readFileSync(join(ROOT, 'public/data/berries.json'), 'utf8')),
).sort((a, b) => a.id - b.id)
const gen4 = berries.map((b) => {
  const file = join(dirs.pokeplatinum, 'res/items/data', `${b.name}_berry.json`)
  if (!existsSync(file)) throw new Error(`no Platinum data for ${b.name}`)
  const d = JSON.parse(readFileSync(file, 'utf8')).berryData
  return [b.name, d.spiciness, d.dryness, d.sweetness, d.bitterness, d.sourness, d.smoothness]
})
if (gen4.length !== 64) throw new Error(`expected 64 Gen 4 berries, got ${gen4.length}`)

const row = (r) => `  ['${r[0]}', [${r.slice(1, 6).join(', ')}], ${r[6]}],`
const out = `/**
 * GENERATED by scripts/build-berry-data.mjs -- do not edit by hand.
 *
 * Each game's berry flavours [spicy, dry, sweet, bitter, sour] and smoothness.
 * Gen 3 from pret/pokeruby @ ${REPOS.pokeruby.sha.slice(0, 7)} and pret/pokeemerald @ ${REPOS.pokeemerald.sha.slice(0, 7)}
 * src/berry.c (identical), in berry-number order: Cheri = 1 ... Enigma = 43
 * (Enigma's row is the placeholder; the real one is e-Reader save data). Gen 4
 * from pret/pokeplatinum @ ${REPOS.pokeplatinum.sha.slice(0, 7)} res/items/data. Read by #19.
 */
export type BerryRow = readonly [name: string, flavors: readonly number[], smoothness: number]

export const GEN3_BERRIES: readonly BerryRow[] = [
${emerald.map(row).join('\n')}
]

export const GEN4_BERRIES: readonly BerryRow[] = [
${gen4.map(row).join('\n')}
]
`
writeFileSync(join(ROOT, 'src/data/berryFlavors.ts'), out)
console.log(`wrote ${emerald.length} Gen 3 and ${gen4.length} Gen 4 berries`)
